(6875364, 1035900, 108069, '<td valign="top">Nice find. Cute shot. I hate to say it, but some more aggressive editing would have likely made this a true standout image. Still great, but lacks a bit of punch.</td>', 'Nice find. Cute shot. I hate to say it, but some more aggressive editing would have likely made this a true standout image. Still great, but lacks a bit of punch.', '2012-10-04 09:12:12.000000', NULL, 1),
(6875368, 1035905, 108069, '<td valign="top">Great scene and very nice gradient to the sky. The massive put in perspective by the even more massive. Nice idea.</td>', 'Great scene and very nice gradient to the sky. The massive put in perspective by the even more massive. Nice idea.', '2012-10-04 09:15:05.000000', NULL, 1),
(6875369, 1035105, 108069, '<td valign="top">Lovely colors and tones pulled together with a sharp silhouette. Sweet shot.</td>', 'Lovely colors and tones pulled together with a sharp silhouette. Sweet shot.', '2012-10-04 09:16:03.000000', NULL, 1),
(6875371, 1035968, 108069, '<td valign="top">Quite nice. Well spotted and great idea... and definitive proof of the existence of UFOs. While I normally enjoy grain, I find that it detracts here a bit, as I just want to melt into the smooth expanse of it all and I''d prefer the tones to wash smoothly into each other. The grain is a bit standoffish to me here. Excellent title.</td>', 'Quite nice. Well spotted and great idea... and definitive proof of the existence of UFOs. While I normally enjoy grain, I find that it detracts here a bit, as I just want to melt into the smooth expanse of it all and I''d prefer the tones to wash smoothly into each other. The grain is a bit standoffish to me here. Excellent title.', '2012-10-04 09:22:02.000000', NULL, 1),
