(6879813, 1035980, 138630, '<td valign="top">I love the way you have used the red to help define your "subject" and set it off from the beautiful flowing lines of the background.  Terrific entry.  Voted earlier.</td>', 'I love the way you have used the red to help define your "subject" and set it off from the beautiful flowing lines of the background.  Terrific entry.  Voted earlier.', '2012-10-10 00:07:26.000000', NULL, 1),
(6879817, 1036057, 138630, '<td valign="top">Beautiful jewel tones - the turquoise against the emerald with the punch of orange is very nice.  Lovely detail, too.  Voted earlier.</td>', 'Beautiful jewel tones - the turquoise against the emerald with the punch of orange is very nice.  Lovely detail, too.  Voted earlier.', '2012-10-10 00:08:47.000000', NULL, 1),
(6879818, 1035588, 138630, '<td valign="top">Just enough light to define this very quiet person.  Stunning work.  Voted earlier.</td>', 'Just enough light to define this very quiet person.  Stunning work.  Voted earlier.', '2012-10-10 00:09:28.000000', NULL, 1),
